#Management wants to know the total revenue generated by the business.
SELECT ROUND(SUM(revenue)) AS total_revenue FROM ecommerce_sales;

#Find the average revenue generated per order.
SELECT ROUND(AVG(revenue), 2) AS average_order_revenue FROM ecommerce_sales;
#Management wants to identify which product category generates the highest revenue.
SELECT product_category, ROUND(SUM(revenue), 2) AS total_revenue, ROUND(AVG(revenue), 2) AS average_revenue FROM ecommerce_sales GROUP BY product_category ORDER BY total_revenue DESC;

#Management wants to understand revenue and order volume by payment method.
SELECT payment_method,COUNT(order_id) AS total_orders,ROUND(SUM(revenue), 2) AS total_revenue,ROUND(AVG(revenue), 2) AS average_payment_value FROM ecommerce_sales GROUP BY payment_method ORDER BY total_revenue DESC;

#Identify the five customers who have spent the most money.
SELECT
    customer_id,
    COUNT(order_id) AS total_orders,
    SUM(revenue) AS total_spending
FROM ecommerce_sales
GROUP BY customer_id
ORDER BY total_spending DESC
LIMIT 5;

#Identify customers who have placed more than 5 orders.
SELECT  customer_id,COUNT(order_id) AS total_orders,ROUND(SUM(revenue)) AS total_spending
FROM ecommerce_sales GROUP BY customer_id HAVING COUNT(order_id) > 5 ORDER BY total_orders DESC;

#Which product categories have sold the highest quantity?
SELECT
    product_category,
    SUM(quantity) AS total_units_sold
FROM ecommerce_sales
GROUP BY product_category
ORDER BY total_units_sold DESC;

CREATE TABLE customers (customer_id INT PRIMARY KEY);
INSERT INTO customers (customer_id) SELECT DISTINCT customer_id FROM ecommerce_sales;
SELECT * FROM customers;

CREATE TABLE categories (product_category VARCHAR(50) PRIMARY KEY);
INSERT INTO categories (product_category) SELECT DISTINCT product_category FROM ecommerce_sales;
SELECT * FROM categories;

#Management wants to identify how much each customer has spent.
SELECT
    c.customer_id,
    COUNT(e.order_id) AS total_orders,
    ROUND(SUM(e.revenue), 2) AS total_spending,
    ROUND(AVG(e.revenue), 2) AS average_order_value
FROM customers c
INNER JOIN ecommerce_sales e
    ON c.customer_id = e.customer_id
GROUP BY c.customer_id
ORDER BY total_spending DESC;

#Management wants to compare revenue and order volume across product categories.
SELECT
    c.product_category,
    COUNT(e.order_id) AS total_orders,
    SUM(e.quantity) AS total_units_sold,
    ROUND(SUM(e.revenue), 2) AS total_revenue,
    ROUND(AVG(e.revenue), 2) AS average_order_value
FROM categories c
INNER JOIN ecommerce_sales e
    ON c.product_category = e.product_category
GROUP BY c.product_category
ORDER BY total_revenue DESC;

#Management wants to compare delivery performance across product categories and identify categories with slower average delivery times.
# Management wants to analyse average delivery time by product category.

SELECT product_category,
    COUNT(order_id) AS total_orders,
    ROUND(AVG(delivery_days), 2) AS average_delivery_days,
    MAX(delivery_days) AS maximum_delivery_days,
    MIN(delivery_days) AS minimum_delivery_days
FROM ecommerce_sales GROUP BY product_category ORDER BY average_delivery_days DESC;